// Facet membership and case-fold tables are generated by the Python public reader.
export const sliceText = (text, size) => [...String(text ?? '')].slice(0, size).join('');
const PY_SPACE = /[\s\u0085\u001c-\u001f]+/u;
export const foldText = (text, map) => [...text].map(char => map[char] ?? char.toLowerCase()).join('');

export function validateFilters(routes, params, rootOverride = '') {
  const root = rootOverride || sliceText(params.get('root'), 100);
  const topic = sliceText(params.get('topic'), 100);
  if (root && !routes.roots.includes(root)) throw new Error('unknown category');
  if (topic && (!Object.hasOwn(routes.topics, topic) || (root && routes.topics[topic] !== root))) throw new Error('unknown topic');
  const facets = Object.fromEntries(Object.keys(routes.facets).map(key => [key, sliceText(params.get(key), 30)]));
  for (const [key, value] of Object.entries(facets)) {
    if (value && !routes.facets[key].includes(value)) throw new Error('unknown filter');
  }
  const pageText = (params.get('page') || '1').trim();
  if (!/^[+-]?\d+(?:_\d+)*$/.test(pageText)) throw new Error('invalid page');
  const page = Number(pageText.replaceAll('_', ''));
  const q = sliceText((params.get('q') || '').replace(/^[\s\u0085\u001c-\u001f]+|[\s\u0085\u001c-\u001f]+$/gu, ''), 100);
  return { root, topic, facets, q, page };
}

export function selectPage(index, params, lang, rootOverride = '') {
  const model = params.get('model') || 'gpt-image';
  const roots = index.model_roots?.[model] ?? index.records.filter(record => record.level === 1).map(record => record.id);
  const topics = Object.fromEntries(index.records.filter(record => record.level === 2).map(record => [record.id, record.chain[0]]));
  const filters = validateFilters({ roots, topics, facets: Object.fromEntries(Object.entries(index.facets).map(([key, values]) => [key, values.map(v => v[0])])) }, params, rootOverride);
  const words = foldText(filters.q, index.casefold).split(PY_SPACE).filter(Boolean);
  const matches = index.records.filter(record => {
    if ((record.model || 'gpt-image') !== model) return false;
    if (filters.root && record.chain[0] !== filters.root) return false;
    if (filters.topic && !record.chain.includes(filters.topic)) return false;
    if (record.level === 2 && !record.look_group && !filters.topic && !filters.q) return false;
    if (!words.every(word => record.labels[lang].hay.includes(word))) return false;
    return Object.entries(filters.facets).every(([key, value]) => !value || record.features[key]?.includes(value));
  });
  const pages = Math.max(1, Math.ceil(matches.length / index.page_size));
  const page = Math.max(1, Math.min(filters.page, pages));
  return { ...filters, ids: matches.slice((page - 1) * index.page_size, page * index.page_size).map(record => record.id), total: matches.length, page, pages, roots, topics };
}
